//! 只归约真实I39事实：先固定区间，缺测/失败保留；不用跨设备墙钟相减。
use crate::{Result,write_json};
use serde_json::{Value,json};
use std::{collections::{BTreeMap,BTreeSet},fs::{self,File},io::{BufRead,BufReader,Write},path::Path};
use super::Driver;
fn n(v:&Value)->Option<u64>{v.as_u64().or_else(||v.as_str()?.parse().ok())}
fn required(v:&Value,k:&str)->Result<u64>{n(&v[k]).ok_or_else(||format!("metric_missing:{k}"))}
fn percentile(v:&[u64],p:f64)->Option<u64>{if v.is_empty(){return None}let mut values=v.to_vec();values.sort_unstable();Some(values[((values.len() as f64*p).ceil() as usize).saturating_sub(1).min(values.len()-1)])}
fn summary(v:&[u64])->Value{json!({"count":v.len(),"p95":percentile(v,0.95),"p99":percentile(v,0.99),"max":v.iter().max(),"mean":if v.is_empty(){None}else{Some(v.iter().map(|x|*x as f64).sum::<f64>()/v.len() as f64)}})}

// 完整Manager入口间隔包含原生模拟、渲染和所有模组窗口；不能用后台Build耗时替代Host帧预算。
fn host_frames(rows:&[&Value],begin:u64,end:u64)->Result<Value>{
 let mut frames=rows.iter().filter(|r|r["event"]=="duration"&&n(&r["stage"])==Some(13)).copied().collect::<Vec<_>>();
 frames.sort_by_key(|r|n(&r["local_us"]));let mut spans=Vec::new();let mut bins=vec![0u64;((end-begin).div_ceil(1000000))as usize];
 let(mut over,mut run,mut run_us,mut longest,mut longest_us)=(0u64,0u64,0u64,0u64,0u64);
 for r in frames{let time=required(r,"local_us")?;let span=required(r,"wall_us")?;spans.push(span);bins[((time-begin)/1000000)as usize]+=1;
  if span>20000{over+=1;run+=1;run_us=run_us.saturating_add(span);longest=longest.max(run);longest_us=longest_us.max(run_us);}else{run=0;run_us=0;}}
 let complete_bins=bins.iter().enumerate().filter(|(i,_)|(*i as u64+1)*1000000<=end-begin).map(|(_,v)|*v).collect::<Vec<_>>();
 let pass=!spans.is_empty()&&over==0&&!complete_bins.is_empty()&&complete_bins.iter().all(|v|*v>=50);
 Ok(json!({"interval_us":summary(&spans),"one_second_frames":bins,"complete_second_min_fps":complete_bins.iter().min(),"over20ms":over,"longest_over20ms_frames":longest,"longest_over20ms_us":longest_us,"pass":pass,"scope":"all measured frames;initial/structure/loading retained by declared window class;no mean-FPS substitution"}))
}

// cursor按进程单调序号读取；后台ring溢出直接写缺测事实，不能提高频率分母。
pub fn drain(driver:&mut dyn Driver,node:&str,token:&str,cursor:&mut u64,out:&mut File)->Result<usize>{let mut count=0;for _ in 0..128{
 let r=driver.command(node,&format!("cs stream_test {token} trace {cursor}"))?;if r.get("ok").map(String::as_str)!=Some("1"){return Err(format!("trace_unavailable:{node}"))}
 let page:Value=serde_json::from_str(r.get("data").ok_or("trace_page_data")?).map_err(|e|e.to_string())?;
 if n(&page["lost"]).unwrap_or(1)>0||n(&page["first"]).is_some_and(|f|*cursor>0&&f>*cursor+1){writeln!(out,"{}",json!({"event":"missing","node":node,"reason":"trace-overflow-or-try-lock-loss","lost":page["lost"]})).map_err(|e|e.to_string())?;}
 let rows=page["rows"].as_array().ok_or("trace_rows")?;for r in rows{let mut r=r.clone();r["node"]=json!(node);writeln!(out,"{r}").map_err(|e|e.to_string())?;count+=1;}
 let next=required(&page,"next")?;if next==*cursor||rows.len()<32{*cursor=next;break}*cursor=next;
 }Ok(count)}

// 对所有连续包子区间核对rate*t+burst，单包/同刻包和补片同样计费。
fn bucket(rows:&[(u64,u64)],rate:u64,burst:u64)->Value{
 let mut rows=rows.to_vec();rows.sort_unstable();let mut sum=0f64;let mut min_before=f64::INFINITY;let mut excess=0f64;let mut at=0;
 for (time,bytes) in &rows{let baseline=sum-rate as f64*(*time as f64/1e6);min_before=min_before.min(baseline);sum+=*bytes as f64;let used=sum-rate as f64*(*time as f64/1e6)-min_before;if used-burst as f64>excess{excess=used-burst as f64;at=*time;}}
 let windows=[100000u64,1000000,10000000].iter().map(|width|{let mut left=0;let mut amount=0u64;let mut max=0;for right in 0..rows.len(){amount+=rows[right].1;while rows[right].0.saturating_sub(rows[left].0)>=*width{amount-=rows[left].1;left+=1;}max=max.max(amount);}json!({"window_us":width,"max_bytes":max,"bound_bytes":rate as f64*(*width as f64/1e6)+burst as f64})}).collect::<Vec<_>>();
 json!({"pass":!rows.is_empty()&&excess<0.001,"packets":rows.len(),"wire_bytes":sum as u64,"rate_byte_s":rate,"burst_bytes":burst,"worst_excess_bytes":excess,"at_local_us":at,"windows":windows})
}
pub fn window(events:&[Value],mark:&Value)->Result<Value>{
 let node=mark["node"].as_str().ok_or("window_node")?;let begin=required(mark,"start_us")?;let end=required(mark,"end_us")?;if end<=begin||mark["fixed_before_start"]!=true{return Err("window_not_fixed_or_invalid".into())}
 let class=mark["class"].as_str().ok_or("window_class_required")?;if !matches!(class,"stable"|"initial"|"host-pause"|"structure"|"visual-neutral"|"damage"|"recovery"){return Err("unknown_predeclared_window_class".into())}let enforce=class=="stable"&&mark["network"]=="N0";
 let rows=events.iter().filter(|e|e["node"]==node&&n(&e["local_us"]).is_some_and(|t|t>=begin&&t<end)).collect::<Vec<_>>();let seconds=(end-begin)as f64/1e6;
 let mut flows:BTreeMap<String,Vec<&Value>>=BTreeMap::new();let mut times:BTreeMap<String,Vec<u64>>=BTreeMap::new();let mut cpu_missing=0;
 for e in &rows{match e["event"].as_str(){Some("flow")=>{let key=format!("{}/{}/{}/{}/{}",e["world"],e["owner"],e["route"],e["range"],e["stage"]);flows.entry(key).or_default().push(e)},Some("duration")=>{let stage=required(e,"stage")?;times.entry(format!("{stage}/wall_us")).or_default().push(required(e,"wall_us")?);if let Some(cpu)=n(&e["cpu_us"]){times.entry(format!("{stage}/cpu_us")).or_default().push(cpu)}else{cpu_missing+=1;}},_=>{}}}
 let mut flow_results=Vec::new();for(key,mut group)in flows{group.sort_by_key(|e|n(&e["local_us"]));let mut seen=BTreeSet::new();group.retain(|e|seen.insert((e["revision"].to_string(),e["sequence"].to_string())));let actual=group.len() as f64/seconds;let ts=group.iter().filter_map(|e|n(&e["local_us"])).collect::<Vec<_>>();let mut gaps=ts.windows(2).map(|v|v[1]-v[0]).collect::<Vec<_>>();if let Some(first)=ts.first(){gaps.push(*first-begin)}if let Some(last)=ts.last(){gaps.push(end-*last)}
  let mut bins=vec![0u64;((end-begin).div_ceil(1000000))as usize];for t in ts{bins[((t-begin)/1000000)as usize]+=1;}
  let sample=group[0];let kind=n(&sample["range"]["kind"]).ok_or("flow_range_kind")?;let stage=required(sample,"stage")?;let minimum=if enforce&&kind==5&&matches!(stage,2|6){Some(29.0)}else if enforce&&kind==6&&matches!(stage,2|6)&&mark["expected60_bodies"].as_array().is_some_and(|b|b.contains(&sample["range"]["body"])){Some(58.0)}else{None};
  let eligible=mark["expected_flows"].as_array().into_iter().flatten().find(|f|f["range"]==sample["range"]&&n(&f["stage"])==Some(stage)).and_then(|f|n(&f["eligible_source_samples"]));let coverage=eligible.filter(|c|*c>0).map(|count|group.len()as f64/count as f64);let coverage_required=enforce&&kind==6&&matches!(stage,2|6);
  flow_results.push(json!({"key":key,"range":sample["range"],"stage":stage,"count":group.len(),"hz":actual,"minimum_hz":minimum,"eligible_source_samples":eligible,"eligible_coverage":coverage,"coverage_pass":if coverage_required{Some(coverage.is_some_and(|v|v>=0.97))}else{None},"frequency_pass":minimum.map(|min|actual>=min),"gap_us":summary(&gaps),"gaps_over100ms":gaps.iter().filter(|g|**g>100000).count(),"one_second_counts":bins,"phase_kind_counts":{"ordinary":group.iter().filter(|e|n(&e["authority_kind"])==Some(0)).count(),"odd":group.iter().filter(|e|n(&e["authority_kind"])==Some(1)).count()}}));
 }
 let mut wire:BTreeMap<String,Vec<(u64,u64)>>=BTreeMap::new();let mut lane_consistent=true;
 for e in &rows{if e["event"]!="packet"||e["direction"]!="host-send"{continue}let t=required(e,"local_us")?;let bytes=required(e,"wire_bytes")?;wire.entry("total".into()).or_default().push((t,bytes));wire.entry(format!("peer/{}",e["connection"])).or_default().push((t,bytes));let lanes=e["lanes"].as_array().ok_or("packet_lanes")?;if lanes.len()!=4{return Err("packet_lane_count".into())}let mut total=0;for(i,lane)in lanes.iter().enumerate(){let b=n(lane).ok_or("lane_bytes")?;total+=b;if b>0{wire.entry(format!("peer/{}/lane/{i}",e["connection"])).or_default().push((t,b));}}lane_consistent&=total==bytes;}
 let bandwidth=wire.into_iter().map(|(k,v)|{let(rate,burst)=if k=="total"{(937500,24576)}else if k.contains("/lane/"){let lane=k.rsplit('/').next().unwrap().parse::<usize>().unwrap();([25000,120000,120000,47500][lane],[2048,4096,4096,8192][lane])}else{(312500,8192)};let b=bucket(&v,rate,burst);(k,b)}).collect::<BTreeMap<_,_>>();
 let mut eligibility=Vec::new();for body in mark["body_deltas"].as_array().into_iter().flatten(){let updates=required(body,"actual_updates")?;let qualified=required(body,"qualified_samples")?;let coverage=if updates==0{None}else{Some(qualified as f64/updates as f64)};eligibility.push(json!({"body":body["body"],"actual_updates":updates,"qualified_samples":qualified,"actual_update_hz":updates as f64/seconds,"qualified_hz":qualified as f64/seconds,"coverage":coverage,"pass":coverage.is_some_and(|v|v>=0.97),"absence_reason":body["absence_reason"]}));}
 let mut witnesses=BTreeMap::<String,[BTreeSet<u64>;2]>::new();for r in &rows{if r["event"]!="body-witness"{continue}let key=format!("{}/{}/{}/{}",r["local"],r["use"],r["shape"],r["binding"]);let stage=required(r,"stage")? as usize;if stage>1{return Err("body_witness_stage".into())}witnesses.entry(key).or_default()[stage].insert(required(r,"tick")?);}
 if !witnesses.is_empty(){eligibility.clear();for(body,stages)in witnesses{let updates=stages[0].len();let qualified=stages[1].intersection(&stages[0]).count();let coverage=if updates==0{None}else{Some(qualified as f64/updates as f64)};eligibility.push(json!({"native_identity":body,"actual_updates":updates,"qualified_samples":qualified,"actual_update_hz":updates as f64/seconds,"qualified_hz":qualified as f64/seconds,"coverage":coverage,"pass":coverage.is_some_and(|v|v>=0.97),"absence_reason":"see same-window Source body status;unqualified updates retained in denominator"}));}}
 let timing=times.iter().map(|(k,v)|(k.clone(),summary(v))).collect::<BTreeMap<_,_>>();let hot=if mark["role"]=="Host"{vec!["12/cpu_us","12/wall_us"]}else{vec!["6/cpu_us"]};let cpu=hot.iter().all(|key|times.get(*key).is_some_and(|v|percentile(v,0.95).is_some_and(|n|n<=2000)&&percentile(v,0.99).is_some_and(|n|n<=4000)));
 let frames=if mark["role"]=="Host"{host_frames(&rows,begin,end)?}else{Value::Null};let frame_pass=mark["role"]!="Host"||frames["pass"]==true;
 let missing=events.iter().filter(|e|e["node"]==node&&e["event"]=="missing").count();
 let expected=mark["expected_flows"].as_array().ok_or("expected_flow_inventory_required")?;let absent=expected.iter().filter(|f|!flow_results.iter().any(|r|r["range"]==f["range"]&&r["stage"]==f["stage"])).cloned().collect::<Vec<_>>();
 let frequency=flow_results.iter().all(|r|r["frequency_pass"]!=false&&r["coverage_pass"]!=false);let gaps=flow_results.iter().filter(|r|r["stage"]==6&&matches!(n(&r["range"]["kind"]),Some(5|6))).all(|r|r["gaps_over100ms"]==0);
 let budget_pass=if mark["role"]=="Host"{!bandwidth.is_empty()&&bandwidth.iter().all(|(key,b)|class=="initial"&&key.contains("/lane/")||b["pass"]==true)}else{true};
 Ok(json!({"node":node,"window":mark,"seconds":seconds,"flows":flow_results,"eligibility":eligibility,"bandwidth":bandwidth,"bandwidth_pass":budget_pass,"lane_total_consistent":lane_consistent,"timing":timing,"host_frames":frames,"frame_pass":frame_pass,"hot_cost_basis":"Host stage12 sums exclusive main-thread collection per frame;stage11 background build is separate","cpu_missing":cpu_missing,"missing_trace":missing,"absent_expected_flows":absent,"N0_stable_performance_enforced":enforce,"frequency_pass":frequency,"gap_pass":gaps,"cpu_pass":cpu,"pass":!expected.is_empty()&&absent.is_empty()&&missing==0&&frequency&&(!enforce||gaps&&cpu&&frame_pass)&&cpu_missing==0&&lane_consistent&&budget_pass&&(!enforce||eligibility.iter().all(|e|e["pass"]==true)&&!eligibility.is_empty())}))
}

// 延迟只接纳同机跨度，状态年龄用同设备收到的Authority锚点和源tick推算；误差显式保留。
pub fn latency(rows:&[Value],network:&str)->Value {
 let mut ages=Vec::new();let mut upper=Vec::new();let mut ack=Vec::new();let mut errors=Vec::new();let mut cold=BTreeMap::new();let mut ready_ms=None;let mut missing=Vec::new();
 for r in rows {match r["event"].as_str(){
  Some("age")=>match(n(&r["authority_tick"]),n(&r["source_tick"]),n(&r["anchor_elapsed_ms"]),n(&r["error_ms"])){
   (Some(a),Some(s),Some(elapsed),Some(error)) if a>=s=>{let age=(a-s).saturating_mul(1000)/60+elapsed;ages.push(age);upper.push(age.saturating_add(error));errors.push(error);if age>500&&r["stale"]!=true{missing.push("over500ms-not-marked-stale");}},
   _=>missing.push("age-anchor-or-source-missing")},
  Some("ack-rtt")=>if r["clock"]=="same-node"{if let Some(ms)=n(&r["elapsed_ms"]){ack.push(ms)}else{missing.push("ack-span")}}else{missing.push("cross-device-clock")},
  Some("cold-dependency")=>{if r["version"].is_null(){missing.push("cold-dependency-identity");continue}if let Some(bytes)=n(&r["compressed_bytes"]){let key=format!("{}/{}",r["world"],r["version"]);if cold.insert(key,bytes).is_some_and(|old|old!=bytes){missing.push("same-version-different-byte-count");}}else{missing.push("cold-byte-count")}},
  Some("cold-ready")=>if r["clock"]=="host-echo-interval"{if let Some(ms)=n(&r["elapsed_ms"]){ready_ms=Some(ready_ms.unwrap_or(0).max(ms))}else{missing.push("cold-ready-span")}}else{missing.push("cold-end-to-end-clock")},
  _=>{}
 }}
 let baseline_bytes=cold.values().copied().sum::<u64>();let p95=if network=="N1"{350}else{200};let max=if network=="N1"{1000}else{500};let age_pass=percentile(&upper,0.95).is_some_and(|v|v<=p95)&&upper.iter().max().is_some_and(|v|*v<=max);
 json!({"age_ms":summary(&ages),"age_upper_bound_ms":summary(&upper),"age_error_ms":summary(&errors),"ack_rtt_ms":summary(&ack),"cold_dependencies_bytes":baseline_bytes,"cold_dependency_count":cold.len(),"cold_ready_ms":ready_ms,"missing":missing,"pass":missing.is_empty()&&age_pass&&baseline_bytes>0&&baseline_bytes<=1048576&&ready_ms.is_some_and(|v|v<=10000)&&!ack.is_empty()})
}

pub fn inputs(rows:&[Value])->Value{let mut sent=BTreeSet::new();let mut expired=BTreeSet::new();let mut offsets=Vec::new();let mut edge_sent=BTreeMap::<String,u64>::new();let mut edges=BTreeMap::<String,u64>::new();let mut consumers=BTreeMap::<String,u64>::new();let mut missing=0;
 for r in rows{match r["event"].as_str(){Some("physical-input")=>{sent.insert(format!("{}/{}/{}",r["participant"],r["generation"],r["sequence"]));},Some("input-expired")=>{expired.insert(format!("{}/{}/{}",r["participant"],r["generation"],r["sequence"]));},Some("input-target")=>{if let(Some(target),Some(authority))=(n(&r["target_tick"]),n(&r["authority_tick"])){offsets.push((target as i128-authority as i128).to_string())}else{missing+=1;}},Some("edge-issued")|Some("edge-consumed")=>{let key=format!("{}/{}/{}/{}",r["participant"],r["generation"],r["sequence"],r["edge"]);let table=if r["event"]=="edge-issued"{&mut edge_sent}else{&mut edges};*table.entry(key).or_default()+=1;},Some("native-consumer")=>{let key=format!("{}/{}/{}",r["participant"],r["body"],r["authority_kind"]);*consumers.entry(key).or_default()+=1;},_=>{}}}
 let ratio=if sent.is_empty(){None}else{Some(expired.intersection(&sent).count() as f64/sent.len() as f64)};
 let edge_pass=!edge_sent.is_empty()&&edge_sent.iter().all(|(key,c)|*c==1&&edges.get(key)==Some(&1))&&edges.keys().all(|k|edge_sent.contains_key(k));
 json!({"physical_commands":sent.len(),"expired":expired.len(),"expired_commands":expired,"expired_ratio":ratio,"target_tick_offsets":offsets,"edge_issued":edge_sent,"edge_consumed":edges,"native_consumers":consumers,"missing":missing,"pass":ratio.is_some_and(|v|v<0.01)&&edge_pass&&!consumers.is_empty()&&missing==0})}
pub fn memory(rows:&[Value])->Value{let mut groups:BTreeMap<String,Vec<(u64,u64)>>=BTreeMap::new();let mut pools=true;for r in rows{if r["event"]!="memory"{continue}if let(Some(t),Some(bytes))=(n(&r["local_us"]),n(&r["private_bytes"])){groups.entry(format!("{}/private",r["node"])).or_default().push((t,bytes));}else{pools=false;}if r["pools"].as_array().is_none_or(|p|p.len()!=3){pools=false;}for p in r["pools"].as_array().into_iter().flatten(){pools&=match(n(&p["current"]),n(&p["high_water"]),n(&p["limit"])){(Some(c),Some(h),Some(l))=>c<=h&&h<=l,_=>false};}}
 let trends=groups.into_iter().map(|(node,mut v)|{v.sort_unstable();let n=v.len() as f64;let x0=v.first().map(|p|p.0).unwrap_or(0);let sx=v.iter().map(|p|(p.0-x0)as f64/1e6).sum::<f64>();let sy=v.iter().map(|p|p.1 as f64).sum::<f64>();let sxx=v.iter().map(|p|((p.0-x0)as f64/1e6).powi(2)).sum::<f64>();let sxy=v.iter().map(|p|(p.0-x0)as f64/1e6*p.1 as f64).sum::<f64>();let denominator=n*sxx-sx*sx;json!({"node":node,"samples":v.len(),"first":v.first(),"last":v.last(),"private_growth_byte_s":if denominator>0.0{Some((n*sxy-sx*sy)/denominator)}else{None},"interpretation":"process trend is separate from owned pools;requires repeated-cycle retirement plateau"})}).collect::<Vec<_>>();let complete=rows.iter().any(|r|r["event"]=="retirement-plateau"&&r["pass"]==true);
 json!({"pools_within_limits":pools,"process_trends":trends,"repeated_retirement_plateau":complete,"pass":pools&&complete&&!trends.is_empty()})}
// 按共同Authority tick/版本关联阶段计数；本地时刻只用于各自频率，绝不相减异机钟。
pub fn pipeline(rows:&[Value])->Value{let mut groups=BTreeMap::<String,BTreeMap<String,BTreeSet<String>>>::new();for r in rows{if r["event"]!="flow"{continue}let key=format!("{}/{}",r["world"],r["range"]);let node_stage=format!("{}/{}/{}",r["node"],r["owner"],r["stage"]);groups.entry(key).or_default().entry(node_stage).or_default().insert(format!("{}/{}",r["revision"],r["sequence"]));}json!(groups.into_iter().map(|(scope,stages)|json!({"scope":scope,"stages":stages.into_iter().map(|(name,versions)|(name,versions.len())).collect::<BTreeMap<_,_>>(),"rule":"retransmission/odd-absence not extra ordinary samples;each owner/Peer separate"})).collect::<Vec<_>>())}
pub fn directory(root:&Path)->Result<()>{
 let marks:Value=serde_json::from_str(&fs::read_to_string(root.join("windows.json")).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;let mut events=Vec::new();let mut raw_bytes=0usize;
 for line in BufReader::new(File::open(root.join("events.jsonl")).map_err(|e|e.to_string())?).lines(){let line=line.map_err(|e|e.to_string())?;raw_bytes=raw_bytes.saturating_add(line.len());if line.len()>1048576||events.len()>=2000000||raw_bytes>128*1024*1024{return Err("tx21_reduce_input_budget;split at predeclared case boundaries,never truncate".into())}events.push(serde_json::from_str::<Value>(&line).map_err(|e|e.to_string())?)}
 let mut windows=Vec::new();let mut latencies=Vec::new();for mark in marks.as_array().ok_or("windows_array")?{windows.push(window(&events,mark)?);let subset=events.iter().filter(|e|e["node"]==mark["node"]&&e["case_id"]==mark["case_id"]&&e["connection"]==mark["connection"]&&e["network"]==mark["network"]).cloned().collect::<Vec<_>>();latencies.push(json!({"node":mark["node"],"case_id":mark["case_id"],"connection":mark["connection"],"network":mark["network"],"result":latency(&subset,mark["network"].as_str().unwrap_or("missing"))}));}
 let result=json!({"format":"isaac.cs.tx21.metrics","version":1,"windows":windows,"latencies":latencies,"pipeline":pipeline(&events),"input":inputs(&events),"memory":memory(&events),"all_cases_acceptance":"I39/I40 separately;metrics alone do not establish E01-E26 pass"});write_json(&root.join("metrics.json"),&result)
}
